1	//! Model-agnostic kernel benchmarking harness.
2	//!
3	//! Every model crate's kernel-report tooling needs the same building blocks: a
4	//! CUDA-event timing loop, latency statistics, accessors over the
5	//! [`KernelCall`] schedule that the report bins serialize, and the rollup that
6	//! folds per-call latencies into per-op / per-call-site report rows. Those
7	//! pieces carry no model knowledge, so they live here and each model crate
8	//! keeps only its own `measure_*` providers (which call into [`measure_loop`])
9	//! and its own schedule walk (which feeds [`accumulate`]).
10	
11	use anyhow::Result;
12	use anyhow::anyhow;
13	use anyhow::bail;
14	use cudarc::driver::sys;
15	use pegainfer_kernels::tensor::DeviceContext;
16	use pegainfer_kernels::tensor::DeviceMatrix;
17	use pegainfer_kernels::tensor::GpuWeight;
18	use pegainfer_kernels::tensor::KernelCall;
19	use pegainfer_kernels::tensor::TensorSpec;
20	use serde::Serialize;
21	
22	#[derive(Clone, Debug, Serialize)]
23	pub struct LatencyStats {
24	    iters: u64,
25	    pub mean_us: f64,
26	    stddev_us: f64,
27	    min_us: f64,
28	    p50_us: f64,
29	    p95_us: f64,
30	    pub p99_us: f64,
31	    max_us: f64,
32	}
33	
34	#[derive(Clone, Debug, Serialize)]
35	pub struct MeasuredCall {
36	    pub supported: bool,
37	    pub reason: Option<String>,
38	    pub stats: Option<LatencyStats>,
39	}
40	
41	impl LatencyStats {
42	    /// All-zero stats for calls that are counted but deliberately not timed
43	    /// (e.g. a no-op collective on a single rank).
44	    pub fn zero(iters: u64) -> Self {
45	        Self {
46	            iters,
47	            mean_us: 0.0,
48	            stddev_us: 0.0,
49	            min_us: 0.0,
50	            p50_us: 0.0,
51	            p95_us: 0.0,
52	            p99_us: 0.0,
53	            max_us: 0.0,
54	        }
55	    }
56	
57	    pub fn from_samples(iters: u64, mut samples: Vec<f64>) -> Result<Self> {
58	        if samples.is_empty() {
59	            bail!("latency sample set is empty");
60	        }
61	        samples.sort_by(f64::total_cmp);
62	        let mean_us = samples.iter().sum::<f64>() / samples.len() as f64;
63	        let stddev_us = if samples.len() > 1 {
64	            let variance = samples
65	                .iter()
66	                .map(|sample| {
67	                    let delta = sample - mean_us;
68	                    delta * delta
69	                })
70	                .sum::<f64>()
71	                / (samples.len() - 1) as f64;
72	            variance.sqrt()
73	        } else {
74	            0.0
75	        };
76	        Ok(Self {
77	            iters,
78	            mean_us,
79	            stddev_us,
80	            min_us: samples[0],
81	            p50_us: percentile(&samples, 0.50),
82	            p95_us: percentile(&samples, 0.95),
83	            p99_us: percentile(&samples, 0.99),
84	            max_us: samples[samples.len() - 1],
85	        })
86	    }
87	}
88	
89	fn percentile(sorted: &[f64], quantile: f64) -> f64 {
90	    let idx = ((sorted.len() as f64 - 1.0) * quantile).ceil() as usize;
91	    sorted[idx.min(sorted.len() - 1)]
92	}
93	
94	/// Time `launch` over `iters` CUDA-event-bracketed iterations after a 3-shot warmup.
95	pub fn measure_loop(
96	    ctx: &DeviceContext,
97	    iters: u64,
98	    mut launch: impl FnMut() -> Result<()>,
99	) -> Result<LatencyStats> {
100	    if iters == 0 {
101	        bail!("iters must be greater than zero");
102	    }
103	    for _ in 0..3 {
104	        launch()?;
105	    }
106	    ctx.sync()?;
107	    let start = ctx
108	        .ctx
109	        .new_event(Some(sys::CUevent_flags::CU_EVENT_DEFAULT))?;
110	    let end = ctx
111	        .ctx
112	        .new_event(Some(sys::CUevent_flags::CU_EVENT_DEFAULT))?;
113	    let mut samples = Vec::with_capacity(iters as usize);
114	    for _ in 0..iters {
115	        start.record(&ctx.stream)?;
116	        launch()?;
117	        end.record(&ctx.stream)?;
118	        samples.push(f64::from(start.elapsed_ms(&end)?) * 1_000.0);
119	    }
120	    ctx.sync()?;
121	    LatencyStats::from_samples(iters, samples)
122	}
123	
124	/// Stable JSON identity of a [`KernelCall`] — op name plus its input/output/attr shapes.
125	pub fn bench_key(call: &KernelCall) -> Result<String> {
126	    Ok(serde_json::to_string(&serde_json::json!({
127	        "op": call.op,
128	        "inputs": call.inputs,
129	        "outputs": call.outputs,
130	        "attrs": call.attrs,
131	    }))?)
132	}
133	
134	pub fn axis(spec: &TensorSpec, name: &str) -> Result<usize> {
135	    spec.axes
136	        .iter()
137	        .find(|axis| axis.name == name)
138	        .map(|axis| axis.size)
139	        .ok_or_else(|| anyhow!("missing axis `{name}` in {}", spec.compact()))
140	}
141	
142	pub fn input<'a>(call: &'a KernelCall, name: &str) -> Result<&'a TensorSpec> {
143	    call.inputs
144	        .iter()
145	        .find(|arg| arg.name == name)
146	        .map(|arg| &arg.spec)
147	        .ok_or_else(|| anyhow!("{} missing input `{name}`", call.label))
148	}
149	
150	pub fn output<'a>(call: &'a KernelCall, name: &str) -> Result<&'a TensorSpec> {
151	    call.outputs
152	        .iter()
153	        .find(|arg| arg.name == name)
154	        .map(|arg| &arg.spec)
155	        .ok_or_else(|| anyhow!("{} missing output `{name}`", call.label))
156	}
157	
158	pub fn attr_usize(call: &KernelCall, name: &str) -> Result<usize> {
159	    call.attrs
160	        .iter()
161	        .find(|attr| attr.name == name)
162	        .ok_or_else(|| anyhow!("{} missing attr `{name}`", call.label))?
163	        .value
164	        .parse()
165	        .map_err(|err| anyhow!("{} invalid attr `{name}`: {err}", call.label))
166	}
167	
168	/// Zero-initialized `rows × cols` device matrix, sized straight from a kernel shape.
169	pub fn zero_matrix(ctx: &DeviceContext, rows: usize, cols: usize) -> Result<DeviceMatrix> {
170	    Ok(DeviceMatrix {
171	        data: ctx.stream.alloc_zeros(rows * cols)?,
172	        rows,
173	        cols,
174	    })
175	}
176	
177	pub fn zero_weight<const OUT: usize, const IN: usize>(
178	    ctx: &DeviceContext,
179	) -> Result<GpuWeight<OUT, IN>> {
180	    GpuWeight::from_device_matrix(zero_matrix(ctx, OUT, IN)?)
181	}
182	
183	// ── Model-report rollup ─────────────────────────────────────────────────
184	//
185	// A model report folds per-call latencies into per-op and per-call-site rows,
186	// each carrying its share of the measured total. The aggregation math is
187	// identical across models; only the schedule walk that feeds it (how a model
188	// handles no-op collectives or ops without a provider) is model-specific, so
189	// that loop stays in each report bin.
190	
191	/// Running aggregate of one op's or call-site's per-call [`LatencyStats`].
192	#[derive(Clone, Copy, Debug, Default)]
193	pub struct Accum {
194	    pub calls: usize,
195	    pub total_us: f64,
196	    pub total_p99_us: f64,
197	    sum_stddev_us: f64,
198	    sum_p99_us: f64,
199	}
200	
201	/// Fold one call's stats into an accumulator.
202	pub fn accumulate(accum: &mut Accum, stats: &LatencyStats) {
203	    accum.calls += 1;
204	    accum.total_us += stats.mean_us;
205	    accum.total_p99_us += stats.p99_us;
206	    accum.sum_stddev_us += stats.stddev_us;
207	    accum.sum_p99_us += stats.p99_us;
208	}
209	
210	/// One per-op row of a model report.
211	#[derive(Clone, Debug, Serialize)]
212	pub struct RollupRow {
213	    pub op: String,
214	    pub calls: usize,
215	    pub total_us: f64,
216	    total_p99_us: f64,
217	    pub per_call_us: f64,
218	    pub stddev_us: f64,
219	    pub p99_us: f64,
220	    pub pct: f64,
221	}
222	
223	/// One per-call-site row of a model report.
224	#[derive(Clone, Debug, Serialize)]
225	pub struct CallSiteRow {
226	    pub call_site: String,
227	    pub op: String,
228	    pub calls: usize,
229	    pub per_call_us: f64,
230	    pub stddev_us: f64,
231	    pub p99_us: f64,
232	    pub total_us: f64,
233	    total_p99_us: f64,
234	    pub pct: f64,
235	}
236	
237	pub fn rollup_row(op: String, accum: Accum, total: f64) -> RollupRow {
238	    let calls = accum.calls.max(1) as f64;
239	    RollupRow {
240	        op,
241	        calls: accum.calls,
242	        total_us: accum.total_us,
243	        total_p99_us: accum.total_p99_us,
244	        per_call_us: accum.total_us / calls,
245	        stddev_us: accum.sum_stddev_us / calls,
246	        p99_us: accum.sum_p99_us / calls,
247	        pct: pct(accum.total_us, total),
248	    }
249	}
250	
251	pub fn call_site_row(call_site: String, op: String, accum: Accum, total: f64) -> CallSiteRow {
252	    let calls = accum.calls.max(1) as f64;
253	    CallSiteRow {
254	        call_site,
255	        op,
256	        calls: accum.calls,
257	        per_call_us: accum.total_us / calls,
258	        stddev_us: accum.sum_stddev_us / calls,
259	        p99_us: accum.sum_p99_us / calls,
260	        total_us: accum.total_us,
261	        total_p99_us: accum.total_p99_us,
262	        pct: pct(accum.total_us, total),
263	    }
264	}
265	
266	/// Percentage share of `value` within `total`, guarding against divide-by-zero.
267	fn pct(value: f64, total: f64) -> f64 {
268	    if total == 0.0 {
269	        0.0
270	    } else {
271	        value / total * 100.0
272	    }
273	}
