    &self,
    hidden: &mut pegainfer_core::tensor::HiddenStates,
) -> Result<()> {
    if let Some(comm) = &self.tp_comm {
        comm.all_reduce_in_place(&mut hidden.data, &ReduceOp::Sum)
            .map_err(|e| anyhow::anyhow!("nccl all-reduce failed: {e:?}"))?;
    }
    Ok(())
